"""Run with: python scripts/test_check_attribution.py"""

import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from check_attribution import find  # noqa: E402


class FindTest(unittest.TestCase):
    def test_flags_tool_credits(self) -> None:
        for text in [
            "Fix\n\nCo-Authored-By: Claude <noreply@anthropic.com>",
            "Co-authored-by: GitHub Copilot <x@y>",
            "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
            "Generated by ChatGPT",
            "Claude-Session: https://claude.ai/code/session_1",
        ]:
            self.assertTrue(find(text), text)

    def test_allows_naming_a_technology(self) -> None:
        for text in [
            "Edit agent calls the Claude API through the adapter",
            "Co-authored-by: Serhat Tay <serhat@example.com>",
            "Gemini and Claude adapters behind one interface",
        ]:
            self.assertEqual(find(text), [], text)


if __name__ == "__main__":
    unittest.main()
